mapper.select:
SELECT #{R1S2} as remType, FIN_PRODUCT.FINPROD_MARKET_ID as finprodId, FIN_PRODUCT.FINPROD_ID as prodId, FIN_PRODUCT.FINPROD_NAME as finprodName, '产品起息' as reminder, REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days ,FIN_PRODUCT.PROFIT_TYPE as oneAttr FROM FIN_PRODUCT INNER JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S2}
LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE( FIN_PRODUCT.VDATE <= #{quaryDate}+REMINDER_SET.DAYS OR FIN_PRODUCT.VDATE <= #{quaryDate} ) AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} AND FIN_PRODUCT.P_FINPROD_ID IS NULL AND FIN_PRODUCT_ADD.ISSUE_STATUS = '03'
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL WHERE FIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND TRD_PRODUCT_DEAL.PS = #{ps_C1} AND TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus_01})
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID )

SELECT #{R1S3} as remType, FIN_PRODUCT.FINPROD_MARKET_ID as finprodId, FIN_PRODUCT.FINPROD_ID as prodId, FIN_PRODUCT.FINPROD_NAME as finprodName, TO_CHAR(FIN_CASH_PLAN.PAY_DATE,'yyyy-MM-dd') || '产品分红' as reminder, FIN_CASH_PLAN.PAY_DATE as mdate, REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days, FIN_PRODUCT.PROFIT_TYPE as oneAttr FROM FIN_CASH_PLAN LEFT JOIN FIN_CASH_INFO ON FIN_CASH_PLAN.CASH_ID = FIN_CASH_INFO.CASH_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S3}
LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE( FIN_CASH_PLAN.PAY_DATE <= #{quaryDate}+REMINDER_SET.DAYS OR FIN_CASH_PLAN.PAY_DATE <= #{quaryDate} ) AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} AND FIN_CASH_PLAN.CASH_TYPE = #{cashType_01} AND FIN_PRODUCT.PROFIT_TYPE in(#{profitType_02},#{profitType_03}) AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1_02} AND FIN_PRODUCT_ADD.ISSUE_STATUS = #{issueStatus_01} AND FIN_PRODUCT.P_FINPROD_ID IS NULL AND FIN_PRODUCT.Mdate > #{quaryDate}
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL WHERE FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_PLAN.MDATE = TRD_PRODUCT_DEAL.MDATE AND (TRD_PRODUCT_DEAL.PS = #{ps_C7} OR TRD_PRODUCT_DEAL.PS = #{ps_C9} OR TRD_PRODUCT_DEAL.PS = 'C10') AND TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus_01} )
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S3} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_CASH_PLAN.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = FIN_CASH_PLAN.PAY_DATE )

SELECT #{R1S5} as remType, FIN_PRODUCT.FINPROD_MARKET_ID as finprodId, FIN_PRODUCT.FINPROD_ID as prodId, FIN_PRODUCT.FINPROD_NAME as finprodName, '产品到期' as reminder, FIN_PRODUCT.PROFIT_TYPE as oneAttr, REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days FROM FIN_PRODUCT
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S5}
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE ( FIN_PRODUCT.MDATE <= #{quaryDate}+REMINDER_SET.DAYS OR FIN_PRODUCT.MDATE <= #{quaryDate} ) AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16} AND FIN_PRODUCT.P_FINPROD_ID IS NULL AND FIN_PRODUCT_ADD.ISSUE_STATUS != '02'
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL WHERE FIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND TRD_PRODUCT_DEAL.PS = #{ps_C5} AND TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus_01})
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S5} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID )

SELECT #{R1S7} as remType, FIN_PRODUCT.FINPROD_MARKET_ID as finprodId, FIN_PRODUCT.FINPROD_ID as prodId, FIN_PRODUCT.FINPROD_NAME as finprodName, '产品的最新净值小于1' as reminder, REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days FROM BOK_POSITION_PRD LEFT JOIN FIN_PRODUCT ON BOK_POSITION_PRD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND FIN_PRODUCT.PROFIT_TYPE = #{profitType_01}
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R1S7}
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE BOK_POSITION_PRD.CDATE = #{quaryDate}
AND FIN_PRODUCT_ADD.ISSUE_STATUS = '01'
AND BOK_POSITION_PRD.TDY_UNIT_VALUE <1 AND FIN_PRODUCT.FINPROD_TYPE2 = #{finType_F16}
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R1S7} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND SYS_ACTIVEREMINDER_INFO.CDATE = #{quaryDate} )

select distinct temp.* from( select T4.remType,T4.assetCode,T4.assetId,T4.assetName,T4.reminder,T4.mdate, T4.menuId,T4.url,T4.lable,T4.dealF,T4.closF,T4.days from ( SELECT #{R3S10} as remType, T2.FINPROD_MARKET_ID as assetCode, T2.FINPROD_ID as assetId, T2.FINPROD_NAME as assetName, TO_CHAR(T1.MDATE,'yyyy-MM-dd')||'付息还本到期' as reminder, T1.MDATE as mdate, REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days
,T3.PORTFOLIO_ID ,T3.SEC_ACCT_ID ,T3.CDATE FROM PTL_PORTFOLIO pp,PTL_SEC_POSITION T3,FIN_CASH_PLAN T1,FIN_PRODUCT T2/*增加组合权限*/
inner join data_auth_notify_inst dani on dani.BUSINESS_ID = T2.FINPROD_ID
and dani.institution_code = #{institutionCode}
LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{R3S10}
T1.FINPROD_ID=T2.FINPROD_ID AND T3.FINPROD_ID=T1.FINPROD_ID AND T3.PORTFOLIO_ID = pp.PORTFOLIO_ID and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' AND T3.CDATE < t1.MDATE AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T3.AMOUNT > 0 AND T3.HODING_TYPE = '03' AND (T1.INT_AMT > 0 or T1.PRIN_AMT > 0) AND T1.FINPROD_TYPE2=#{finType_F17}
AND ( ( T1.MDATE <= to_date(#{quaryDateStr},'yyyy-mm-dd')+REMINDER_SET.DAYS and to_date(#{quaryDateStr},'yyyy-mm-dd') <= T1.MDATE ) or ( T1.PAY_DATE <= to_date(#{quaryDateStr},'yyyy-mm-dd')+REMINDER_SET.DAYS and to_date(#{quaryDateStr},'yyyy-mm-dd') <= T1.PAY_DATE ) )
AND T1.CASH_TYPE IN (#{cashType_01},#{cashType_02},#{cashType_03}) /*不存在生效的交易*/ and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{tradeStatus_01} AND TPDA.IS_CANCEL = 'N' and T1.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T3.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND ((TPDA.CHL_ID is NULL and t3.sec_acct_id='999999') OR TPDA.CHL_ID = T3.SEC_ACCT_ID)) /*不存在流程中的当期或之前的交易*/ AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{tradeStatus_01} AND TPDA.IS_CANCEL = 'N' and T1.MDATE >= TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T3.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND ((TPDA.CHL_ID is NULL and t3.sec_acct_id='999999') OR TPDA.CHL_ID = T3.SEC_ACCT_ID))
)T4
left join PTL_SEC_POSITION tpsp on tpsp.HODING_TYPE = '03' AND tpsp.PORTFOLIO_ID = T4.PORTFOLIO_ID AND tpsp.SEC_ACCT_ID = T4.SEC_ACCT_ID AND tpsp.FINPROD_ID = T4.assetId AND tpsp.CDATE > T4.CDATE AND tpsp.CDATE < t4.mdate left join SYS_ACTIVEREMINDER_INFO on SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S10} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = t4.assetCode AND SYS_ACTIVEREMINDER_INFO.MDATE = T4.MDATE inner join PTL_PORTFOLIO_AUTHORITY ppa on T4.PORTFOLIO_ID = T4.PORTFOLIO_ID
and ppa.USER_ID = #{userId}
where tpsp.HODING_TYPE is null AND SYS_ACTIVEREMINDER_INFO.SEQNO IS NULL )temp
left join TRD_PRODUCT_DEAL T3 on temp.assetId = T3.FINPROD_ID and temp.mdate = T3.MDATE AND T3.IS_CANCEL = 'N' AND T3.TRADE_STATUS = #{tradeStatus_01} AND T3.PS IN (#{returnThis},#{ps_T22},#{ps_T23}) where T3.IS_CANCEL IS NULL

SELECT DISTINCT #{R7S3} AS remType, fp.finprod_market_id assetCode, fp.Finprod_Abbr assetName, DECODE(fp.manager,NULL,DECODE(fp.sponsor,NULL,DECODE(fp.invest_adviser,NULL,DECODE(fp.issuer,NULL,'融资人','发行人'),'投资顾问'),'担保人'),'管理人') ||'存在声誉风险' AS reminder, mci.CUSTOMER_ID AS orgId, mci.CUSTOMER_NAME AS orgName, sas.MENU_ID AS menuId, sas.URL, sas.LABLE AS lable, sas.DEALF AS dealF, sas.CLOSF AS closF, sas.DAYS FROM FIN_PRODUCT fp LEFT JOIN SYS_ACTIVEREMINDER_SET sas ON 1=1 LEFT JOIN MST_CUSTOMER_INFO mci ON mci.CUSTOMER_ID =DECODE(fp.manager,NULL,DECODE(fp.sponsor,NULL,DECODE(fp.invest_adviser,NULL,DECODE(fp.issuer,NULL,fp.financier,fp.issuer),fp.invest_adviser),fp.sponsor),fp.manager) WHERE sas.REM_TYPE =#{R7S3} AND fp.finprod_type2 IN ('F01','F06','F07','F10','F17','F18')
AND mci.Customer_Id IN (select org.orgid from (SELECT DISTINCT orgId FROM (SELECT DISTINCT t2.issuer, t2.financier, t2.manager, t2.sponsor, t2.invest_adviser FROM PTL_SEC_POSITION t1 LEFT JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID = t2.FINPROD_ID WHERE t1.amount != 0
and ( t2.issuer IS NOT NULL OR t2.financier IS NOT NULL OR t2.manager IS NOT NULL OR t2.sponsor IS NOT NULL OR t2.invest_adviser IS NOT NULL ) ) UNPIVOT(orgId FOR NAME IN(issuer, financier, manager, sponsor, invest_adviser)) GROUP BY orgId) org join INF_ORG_NEGATIVE_NEWS t4 on org.orgid = t4.org_no left join MST_CUSTOMER_INFO t5 on org.orgid = t5.customer_id where 1=1 and t4.pub_date <= #{quaryDate}
) AND fp.Finprod_Market_Id not in (SELECT S.FINPROD_ID FROM SYS_ACTIVEREMINDER_INFO S left Join FIN_PRODUCT t2 on S.FINPROD_ID =t2.Finprod_Market_Id WHERE S.REM_TYPE =#{R7S3} AND S.EFFFLAG =#{noFlag} ) AND EXISTS ( SELECT 1 FROM PTL_SEC_POSITION T1 WHERE finprod_id = fp.finprod_id AND amount != 0)

SELECT #{bondDuration} AS reminderType,assetCode, assetName,#{due} AS reminder,'link' AS operating FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{bond} AND T1.PAY_DATE_UNADJUST-to_number(#{configurationDays}) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{bond} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
) AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S5} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = FIN_CASH_PLAN.PAY_DATE_UNADJUST
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)
)

SELECT #{projectAssetDuration} AS reminderType,assetCode, assetName,#{due} AS reminder,'link' AS operating FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{projectAssets} AND T1.PAY_DATE_UNADJUST-to_number(#{configurationDays}) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{projectAssets} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
) AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S8} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = FIN_CASH_PLAN.PAY_DATE_UNADJUST
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)
)

SELECT #{planRateDuration} AS reminderType,assetCode, assetName,#{due} AS reminder,'link' AS operating FROM ( SELECT T2.FINPROD_ID AS assetCode, T2.FINPROD_ABBR AS assetName FROM FIN_CASH_PLAN T1,FIN_PRODUCT T2
T1.FINPROD_ID=T2.FINPROD_ID AND T1.FINPROD_TYPE2=T2.FINPROD_TYPE2 AND T1.FINPROD_TYPE2=#{plannedAssets} AND T1.PAY_DATE_UNADJUST-to_number(#{configurationDays}) <= #{quaryDate} AND T1.PAY_DATE_UNADJUST >= #{quaryDate} AND T1.CASH_TYPE IN (#{midIncome},#{midReturn},#{dueRepayment}) AND NOT EXISTS( SELECT 1 FROM TRD_PRODUCT_DEAL T3
T1.VDATE = T3.VDATE AND T1.MDATE = T3.MDATE AND T1.PAY_DATE = T3.SETTLE_DATE AND T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 = #{plannedAssets} AND T3.IS_CANCEL = #{no} AND T3.PS IN (#{returnThis},#{maturity},#{purchase})
) AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S15} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_MARKET_ID AND SYS_ACTIVEREMINDER_INFO.MDATE = FIN_CASH_PLAN.PAY_DATE_UNADJUST
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)
)

SELECT #{R4S1} as remType, T2.FINPROD_ID as assetId, T2.Finprod_Market_Id as assetCode, T2.FINPROD_ABBR as assetName,
to_char(T1.ACT_EXERCISE_DATE , 'yyyy-MM-dd') ||'债券行权'|| decode(T1.EXERCISE_TYPE,'01','赎回','02','回售',T1.EXERCISE_TYPE) as reminder,
REMINDER_SET.MENU_ID as menuId, REMINDER_SET.URL as url, REMINDER_SET.LABLE as lable, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF, REMINDER_SET.DAYS as days FROM FIN_EXERCISE_PLAN T1 LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID
LEFT JOIN( SELECT SYS_ACTIVEREMINDER_SET.DAYS, SYS_ACTIVEREMINDER_SET.MENU_ID, SYS_ACTIVEREMINDER_SET.URL, SYS_ACTIVEREMINDER_SET.LABLE, SYS_ACTIVEREMINDER_SET.DEALF, SYS_ACTIVEREMINDER_SET.CLOSF FROM SYS_ACTIVEREMINDER_SET WHERE SYS_ACTIVEREMINDER_SET.REM_TYPE = #{R4S1} )REMINDER_SET ON 1=1
where T1.EXERCISE_DATE-REMINDER_SET.DAYS <=#{quaryDate}
AND T1.ACT_EXERCISE_DATE >= #{quaryDate}
AND T1.EXERCISE_STATUS = #{unauthorized} AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R4S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = T2.FINPROD_MARKET_ID
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)

SELECT 'R3S1' as remType, fp.FINPROD_ID as assetId, fp.Finprod_Market_Id as assetCode, fp.FINPROD_NAME as assetName, decode(tpd.PS,'T24','回款确认','T02','卖出','T11','现金分红') as reminder, T5.MENU_ID as menuId, T5.URL as url, T5.LABLE as lable, T5.DEALF as dealF, T5.CLOSF as closF, T5.DAYS as days FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (SELECT * FROM WFL_TRD_PRODUCT_DEAL MINUS SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = 'T24') T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = '01') tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1
INNER JOIN DATA_AUTH_NOTIFY_INST dani ON dani.BUSINESS_ID = tpd.PORTFOLIO_ID AND dani.INSTITUTION_CODE = #{institution} AND dani.DATA_TYPE = 'PTL01'
WHERE tpd.FINPROD_TYPE2 = #{fund} AND tpd.PS in (#{ps_T24}, #{ps_T02}, #{ps_T11}) and fpt.type_6 = #{nonmonetaryFund} AND T5.REM_TYPE = #{R3S1} AND tpd.TRADE_DATE - to_number(T5.DAYS) <= #{quaryDate} AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S1} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_MARKET_ID
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)

SELECT 'R3S2' as remType, fp.FINPROD_ID as assetId, fp.Finprod_Market_Id as assetCode, fp.FINPROD_NAME as assetName, decode(tpd.PS,'T24','回款确认','T02','卖出','T11','现金分红') as reminder, T5.MENU_ID as menuId, T5.URL as url, T5.LABLE as lable, T5.DEALF as dealF, T5.CLOSF as closF, T5.DAYS as days FROM (SELECT distinct '01' VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_DATE, T1.SETTLE_DATE, T1.WORKFLOW_ID, T1.B_TRADE_ID, T2.PORTFOLIO_ID FROM (SELECT * FROM WFL_TRD_PRODUCT_DEAL MINUS SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS IN ('T24')) T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID WHERE (T1.IS_CANCEL is null or T1.IS_CANCEL = #{noFlag}) and T1.TRADE_STATUS = '01') tpd LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpd.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN SYS_ACTIVEREMINDER_SET T5 on 1 = 1
INNER JOIN DATA_AUTH_NOTIFY_INST dani ON dani.BUSINESS_ID = tpd.PORTFOLIO_ID AND dani.INSTITUTION_CODE = #{institution} AND dani.DATA_TYPE = 'PTL01'
WHERE tpd.FINPROD_TYPE2 = #{fund} AND tpd.PS in ('T24', #{ps_T02}, #{ps_T11}) and fpt.type_6 = #{monetaryFund} AND T5.REM_TYPE = #{R3S2} AND tpd.TRADE_DATE - to_number(T5.DAYS) <= #{quaryDate} AND tpd.TRADE_DATE >= #{quaryDate} AND NOT EXISTS (SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = #{R3S2} AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = fp.FINPROD_MARKET_ID
and SYS_ACTIVEREMINDER_INFO.INSTITUTION_CODE = #{institutionCode}
)

select remType,assetCode,assetId,assetName,reminder,menuId,url,lable,dealF,closF,days,mDate
from(

)
group by remType,assetCode,assetId,assetName,reminder,menuId,url,lable,dealF,closF,days,mDate

SELECT A.SUP_FREQUENCY as supFrequency, W.FREQUENCY as frequency, A.PORTFOLIO_ID, A.IND_ID as indId, B.IND_NAME as indName, B.SUP_TYPE as supType, A.SUP_DATE as supDate, A.SUP_VAL AS supVal, A.WARN_COND as warnCond, A.APPROVE_COND as approveCond, A.FOUL_COND as foulCond, A.SUP_STAT as supStat, A.FOUL_DAYS as foulDays, A.SUP_UNITE_STAT as supUniteStat, A.MATH_PROCESS as mathProcess, B.MEMO as memo, B.IND_TYPE as indType, (CASE WHEN C.PORTFOLIO_LEVEL = #{PORTFOLIO_LEVEL_01,jdbcType = VARCHAR} THEN (SELECT D.PORTFOLIO_NAME FROM PTL_PORTFOLIO D WHERE D.PORTFOLIO_ID = A.PORTFOLIO_ID) ELSE (SELECT E.PTL_BAG_NAME FROM RSK_PORTFOLIO_PACKAGE E WHERE E.PTL_BAG_ID = A.PORTFOLIO_ID) END ) groupName, (SELECT count(1) FROM RSK_ISUP_POINT_DET_VAL t WHERE t.IND_ID=A.IND_ID AND T.PORTFOLIO_ID=A.PORTFOLIO_ID AND T.SUP_FREQUENCY=A.SUP_FREQUENCY AND T.SUP_DATE=A.SUP_DATE) AS mxCount, #{remType} as remType, REMINDER_SET.DEALF as dealF, REMINDER_SET.CLOSF as closF FROM RSK_ISUP_POINT_VAL A INNER JOIN RSK_PORTFOLIO_INDICATOR C ON C.PORTFOLIO_ID = A.PORTFOLIO_ID AND C.IND_ID = A.IND_ID AND NOT EXISTS ( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE REM_TYPE = #{remType} AND FINPROD_ID = A.PORTFOLIO_ID AND FINPROD_NAME = A.IND_ID AND REMARK = A.SUP_FREQUENCY AND CDATE = A.SUP_DATE AND EFFFLAG = #{noFlag} ) INNER JOIN RSK_ISUP_INDICATOR B ON B.IND_ID = A.IND_ID LEFT JOIN PTL_PORTFOLIO D ON D.PORTFOLIO_ID = A.PORTFOLIO_ID LEFT JOIN RSK_PORTFOLIO_PACKAGE E ON E.PTL_BAG_ID = A.PORTFOLIO_ID LEFT JOIN (select A.PORTFOLIO_ID AS ID,COUNT(A.SUP_STAT) AS frequency from RSK_ISUP_POINT_VAL A
A.SUP_STAT <> 'NORMAL' AND A.SUP_DATE = #{quaryDate}
group by A.PORTFOLIO_ID) W ON W.ID = A.PORTFOLIO_ID LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = #{remType} INNER JOIN ( SELECT A.PORTFOLIO_ID, A.IND_ID, A.SUP_DATE, MAX(A.UPDATE_TIME) AS updateTime FROM RSK_ISUP_POINT_VAL A GROUP BY A.PORTFOLIO_ID, A.IND_ID, A.SUP_DATE) M ON A.UPDATE_TIME = M.updateTime AND M.PORTFOLIO_ID = A.PORTFOLIO_ID AND M.IND_ID = A.IND_ID AND M.SUP_DATE = A.SUP_DATE
A.SUP_DATE = #{quaryDate}
AND A.SUP_STAT IN
#{item}
AND (case when A.SUP_UNITE_STAT is null then A.SUP_STAT else A.SUP_UNITE_STAT end) <> #{infParam, jdbcType=VARCHAR}
ORDER BY A.SUP_DATE DESC

select * from(select distinct a.assetCode assetCode, a.assetName assetName, a.remType remType, a.reminder reminder, a.mdate mdate, a.days days, a.menuId menuId, a.url url, a.lable lable, a.dealF dealF, a.closF closF from ( select case when wtpd.trade_id is not null then '04' else '' end paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S1' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE is not null and wtp.YIELD is not null AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('01') union all select bo.PAY_TYPE paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S1' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win and bobp.TRADE_ID is null AND BOBP.WIN_PRICE IS NOT NULL AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('01') minus select bo.PAY_TYPE paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S1' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE is not null and wtp.YIELD is not null AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('01') union all select case when bobp.trade_id is not null then '05' else '' end paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S1' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win AND bobp.trade_id is not NULL AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('01')
union all
/*场内债券缴款查询*/
select case when wtpd.trade_id is not null then '04' else '' end paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S2' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE is not null and wtp.YIELD is not null AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('03', '04') union all select bo.PAY_TYPE paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S2' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win and bobp.TRADE_ID is null AND BOBP.WIN_PRICE IS NOT NULL AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('03', '04') minus select bo.PAY_TYPE paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpd on wtpd.entrust_id = ebp.entrust_id LEFT JOIN WFL_TRD_PRODUCT_DEAL wtp on wtp.TRADE_ID = wtpd.TRADE_ID LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S2' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win and bobp.WIN_PRICE is not null and wtp.YIELD is not null AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('03', '04') union all select case when bobp.trade_id is not null then '05' else '' end paymentStatus, /*缴款状态*/ ee.ENTRUST_STATUS entrustStatus, /*委托状态*/ fp.FINPROD_MARKET_ID assetCode, /*资产代码*/ fp.finprod_name assetName, /*资产名称*/ 'R11S1' remType, to_char(bo.PAY_DATE, 'yyyy-MM-dd') || '_分销缴款' reminder, bo.PAY_DATE mdate, /*缴款日*/ REMINDER_SET.DAYS days, REMINDER_SET.MENU_ID menuId, REMINDER_SET.URL url, REMINDER_SET.LABLE lable, REMINDER_SET.DEALF dealF, REMINDER_SET.CLOSF closF, bobp.ENTRUST_ID entrustId, /*委托编号*/ bobp.BID_ID bidId, /*投标编号*/ ee.portfolio_id portfolioId, /*组合代码*/ pp.portfolio_name portfolioName, /*组合名称*/ fp.FINPROD_ID finprodId, /*资产代码*/ ee.TRADE_MARKET tradeMarket, /*交易场所*/ bo.PAY_TYPE payType, /*缴款方式*/ ebp.bid_prin_amt bidPrinAmt, /*投标券面总额*/ bobp.WIN_PRIN_AMT winPrinAmt, /*中标券面总额*/ bobp.BID_PRICE * 100 bidPrice, /*投标标位%*/ bobp.WIN_PRICE * 100 winPrice, /*中标标位%*/ bo.BID_DATE bidDate, /*投标日*/ bobp.WIN_CPRICE winCprice /*中标净价*/ from BID_ORDER_BID_PRICE bobp left join ETR_ENTRUST ee on bobp.entrust_id = ee.entrust_id left join PTL_PORTFOLIO pp on ee.portfolio_id = pp.portfolio_id left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.finprod_id left join BID_ORDER bo on bo.bid_id = bobp.bid_id LEFT JOIN ETR_ENTRUST_BID_PRICE ebp on ebp.entrust_id = bobp.entrust_id and ebp.BID_PRICE = bobp.BID_PRICE LEFT JOIN SYS_ACTIVEREMINDER_SET REMINDER_SET ON REMINDER_SET.REM_TYPE = 'R11S2' where 1 = 1 and bobp.is_win = 'Y' and bo.is_win = bobp.is_win AND bobp.trade_id is not NULL AND nvl(ee.TRADE_MARKET, fp.TRADE_MARKET) in ('03', '04')
) a where a.entrustStatus != '06' and a.paymentStatus != '04' and a.paymentStatus != '05' and a.mdate <= #{quaryDate} + a.days and a.mdate >= #{quaryDate} AND NOT EXISTS( SELECT 1 FROM SYS_ACTIVEREMINDER_INFO WHERE SYS_ACTIVEREMINDER_INFO.REM_TYPE = 'R11S1' AND SYS_ACTIVEREMINDER_INFO.EFFFLAG = #{noFlag} AND SYS_ACTIVEREMINDER_INFO.FINPROD_ID = a.assetCode AND SYS_ACTIVEREMINDER_INFO.MDATE = a.mdate ))
